// HasSourceAsset applies the HasEdge predicate on the "source_asset" edge.
func HasSourceAsset() predicate.CreativeVariant {
	return predicate.CreativeVariant(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, SourceAssetTable, SourceAssetColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasSourceAssetWith applies the HasEdge predicate on the "source_asset" edge with a given conditions (other predicates).
func HasSourceAssetWith(preds ...predicate.Asset) predicate.CreativeVariant {
	return predicate.CreativeVariant(func(s *sql.Selector) {
		step := newSourceAssetStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasApproval applies the HasEdge predicate on the "approval" edge.
func HasApproval() predicate.CreativeVariant {
	return predicate.CreativeVariant(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2O, false, ApprovalTable, ApprovalColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasApprovalWith applies the HasEdge predicate on the "approval" edge with a given conditions (other predicates).
func HasApprovalWith(preds ...predicate.Approval) predicate.CreativeVariant {
	return predicate.CreativeVariant(func(s *sql.Selector) {
		step := newApprovalStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.CreativeVariant) predicate.CreativeVariant {
	return predicate.CreativeVariant(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.CreativeVariant) predicate.CreativeVariant {
	return predicate.CreativeVariant(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.CreativeVariant) predicate.CreativeVariant {
	return predicate.CreativeVariant(sql.NotPredicates(p))
}
